module Counter(
  input        clock,
               en,
  input  [7:0] a,
  output [7:0] q
);

  reg [7:0] r;
  always @(posedge clock) begin
    if (en) begin
      trace({24'h0, r});
      r <= r + a;
    end
  end // always @(posedge)
  assign q = r;
endmodule

module Watcher(
  input        clock,
               en,
  input  [7:0] a,
               b,
  output [7:0] q
);

  reg [7:0] r;
  always @(posedge clock) begin
    if (en) begin
      check(a, b);
      trace({24'h0, a});
    end
    r <= a ^ b;
  end // always @(posedge)
  assign q = r;
endmodule

module Mixer(
  input  [7:0] a,
               b,
  output [7:0] q
);

  assign q = {a[3:0], b[7:4]} ^ {b[3:0], a[7:4]};
endmodule

module DpiTop(
  input        clock,
               en,
  input  [7:0] a,
               b,
  output [7:0] q
);

  wire [7:0] _counter_q;
  wire [7:0] _watcher_q;
