    .a     (a),
    .q     (_counter_q)
  );
  Watcher watcher (
    .clock (clock),
    .en    (en),
    .a     (a),
    .b     (b),
    .q     (_watcher_q)
  );
  Mixer mixer (
    .a (_counter_q),
    .b (_watcher_q),
    .q (q)
  );
endmodule
